    return syms, np.array(xyz)
s,p = read_xyz("answer.xyz")
def d(i,j): return float(np.linalg.norm(p[i]-p[j]))
bonds = [
 (7,8,"C=C vinyl"),(8,9),(9,15),(15,16),(16,17),(17,7),
 (9,10),(10,12),(12,14),(14,15),(10,11,"N-Me"),(12,13,"C=O"),
 (17,18),(18,19,"C#N"),
]
for b in bonds:
    i,j = b[0],b[1]
    print(f"{s[i]}{i}-{s[j]}{j}: {d(i,j):.3f}")
# H assignments sanity: H on each sp3 C
for c in (9,15,17,14,16,11):
    hs=[k for k in range(len(s)) if s[k]=='H' and d(c,k)<1.25]
    print(f"H on C/N {c}:", hs, [round(d(c,k),2) for k in hs])
